#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def write(path, content):
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8', newline='\n')

def replace_once(path, old, new):
    target = ROOT / path
    text = target.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'guard failed: {path}: expected one anchor, found {count}')
    target.write_text(text.replace(old, new, 1), encoding='utf-8', newline='\n')

write('module.prop', 'id=pixel-10-pro-xl-thermal-fix\nname=Pixel 10 Thermal & Memory Control\nversion=2.0.0-alpha.3-dev.14\nversionCode=1016225\nauthor=Lycidias93, marx161, Codecity001\ndescription=V2 Alpha 3 dev.14: safe adaptive Emerald Hill defaults, physical devfreq alias deduplication, migration-safe restore, stock LMK policy, and explicit ZRAM/EH risk observability.\nupdateJson=https://raw.githubusercontent.com/Lycidias93/pixel-10-pro-xl-thermal-fix/main/update.json\n')
write('tools/zram/emerald-hill-control.sh', '#!/system/bin/sh\n# Optional Emerald Hill devfreq maximum-frequency minimum lock for lz77eh ZRAM.\n# This never requests a frequency above the kernel-exposed maximum OPP.\n# It can increase power and heat by preventing adaptive downclocking.\nset -eu\n\nID="${ID:-pixel-10-pro-xl-thermal-fix}"\nMODDIR="${MODDIR:-/data/adb/modules/$ID}"\nCONFIG_FILE="${ZRAM_CONFIG_FILE:-/data/adb/$ID/config.env}"\nSTATE_DIR="${ZRAM_EH_STATE_DIR:-/data/adb/$ID/zram-eh}"\nBASELINE_FILE="$STATE_DIR/baseline.tsv"\nSTATUS_FILE="$STATE_DIR/status.env"\nNORMALIZE="$MODDIR/tools/zram/config-normalize.sh"\nROOTS="${ZRAM_EH_DEVFREQ_ROOTS:-/sys/class/devfreq/* /sys/devices/platform/*/devfreq/*}"\nMODE="${1:-status}"\n\nSTATUS_PATH=none\nSTATUS_ORIGINAL_MIN=none\nSTATUS_OBSERVED_MAX=none\nSTATUS_ALIASES_SKIPPED=0\nRESTORE_NODES=0\nRESTORE_ALIASES_SKIPPED=0\nRESTORE_FAILED=0\n\ncfg_get() {\n  [ -r "$CONFIG_FILE" ] || return 0\n  grep -E "^$1=" "$CONFIG_FILE" 2>/dev/null | tail -n 1 | sed "s/^$1=//" | tr -d \'\\r\'\n}\n\nis_uint() {\n  case "$1" in \'\'|*[!0-9]*) return 1 ;; *) return 0 ;; esac\n}\n\ncanonical_dir() {\n  dir="$1"\n  resolved="$(readlink -f "$dir" 2>/dev/null || true)"\n  if [ -n "$resolved" ]; then\n    printf \'%s\\n\' "$resolved"\n    return 0\n  fi\n  (CDPATH= cd -- "$dir" 2>/dev/null && pwd -P) || printf \'%s\\n\' "$dir"\n}\n\nis_eh_node() {\n  dir="$1"\n  [ -d "$dir" ] || return 1\n  [ -r "$dir/min_freq" ] || return 1\n  [ -w "$dir/min_freq" ] || return 1\n  [ -r "$dir/max_freq" ] || return 1\n  label="${dir##*/} $(cat "$dir/name" 2>/dev/null || true)"\n  lower="$(printf \'%s\' "$label" | tr \'A-Z\' \'a-z\')"\n  case "$lower" in\n    *emerald*|*lz77*|eh|eh.*|*.eh|*.eh.*|eh_freq|eh_freq\\ *|eh-freq|eh-freq\\ *|*eh-devfreq*) return 0 ;;\n    *) return 1 ;;\n  esac\n}\n\nfrequency_available() {\n  dir="$1"\n  target="$2"\n  file="$dir/available_frequencies"\n  [ -s "$file" ] || return 0\n  for value in $(cat "$file" 2>/dev/null || true); do\n    [ "$value" = "$target" ] && return 0\n  done\n  return 1\n}\n\nstatus_write() {\n  state="$1"\n  detail="$2"\n  nodes="$3"\n  target="$4"\n  mkdir -p "$STATE_DIR" 2>/dev/null || true\n  tmp="$STATUS_FILE.tmp.$$"\n  {\n    printf \'%s\\n\' \'schema=pixel-zram-eh-status-v2\'\n    printf \'%s\\n\' "state=$state"\n    printf \'%s\\n\' "detail=$detail"\n    printf \'%s\\n\' "nodes=$nodes"\n    printf \'%s\\n\' "aliases_skipped=$STATUS_ALIASES_SKIPPED"\n    printf \'%s\\n\' "path=$STATUS_PATH"\n    printf \'%s\\n\' "original_min=$STATUS_ORIGINAL_MIN"\n    printf \'%s\\n\' "observed_max=$STATUS_OBSERVED_MAX"\n    printf \'%s\\n\' "target=$target"\n    printf \'%s\\n\' \'apply_mode=one_shot_post_bootguard\'\n    printf \'%s\\n\' "configured=$(cfg_get ZRAM_EMERALD_OC)"\n    printf \'%s\\n\' "eh_risk_ack=$(cfg_get ZRAM_EH_RISK_ACK)"\n    printf \'%s\\n\' "last_choice=$(cfg_get LAST_ZRAM_100P)"\n    printf \'%s\\n\' "zram_enabled=$(cfg_get ENABLE_ZRAM_100P)"\n    printf \'%s\\n\' "updated_epoch=$(date +%s 2>/dev/null || printf unknown)"\n  } > "$tmp"\n  chmod 0600 "$tmp" 2>/dev/null || true\n  mv "$tmp" "$STATUS_FILE"\n}\n\nrestore_file() {\n  source_file="$1"\n  RESTORE_NODES=0\n  RESTORE_ALIASES_SKIPPED=0\n  RESTORE_FAILED=0\n  [ -s "$source_file" ] || return 0\n\n  seen="$STATE_DIR/restore-seen.tmp.$$"\n  : > "$seen"\n  tab="$(printf \'\\t\')"\n\n  while IFS="$tab" read -r c1 c2 c3 c4 c5 extra; do\n    [ "$c1" = path ] && continue\n    [ -n "$c1" ] || continue\n\n    if [ -n "$c5" ]; then\n      dir="$c1"\n      identity="$c2"\n      original_min="$c3"\n    else\n      dir="$c1"\n      identity="$(canonical_dir "$dir")"\n      original_min="$c2"\n    fi\n\n    if [ -n "$extra" ] || ! is_uint "$original_min" || [ ! -w "$dir/min_freq" ]; then\n      RESTORE_FAILED=$((RESTORE_FAILED + 1))\n      continue\n    fi\n\n    [ -n "$identity" ] || identity="$(canonical_dir "$dir")"\n    if grep -Fqx "$identity" "$seen" 2>/dev/null; then\n      RESTORE_ALIASES_SKIPPED=$((RESTORE_ALIASES_SKIPPED + 1))\n      continue\n    fi\n    printf \'%s\\n\' "$identity" >> "$seen"\n\n    if printf \'%s\\n\' "$original_min" > "$dir/min_freq" 2>/dev/null &&\n       [ "$(cat "$dir/min_freq" 2>/dev/null || true)" = "$original_min" ]; then\n      RESTORE_NODES=$((RESTORE_NODES + 1))\n    else\n      RESTORE_FAILED=$((RESTORE_FAILED + 1))\n    fi\n  done < "$source_file"\n\n  rm -f "$seen" 2>/dev/null || true\n  [ "$RESTORE_FAILED" -eq 0 ] 2>/dev/null\n}\n\nnormalize_config() {\n  if [ -r "$NORMALIZE" ]; then\n    ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$NORMALIZE" >/dev/null 2>&1 || true\n  fi\n}\n\napply_lock() {\n  normalize_config\n  [ -r "$CONFIG_FILE" ] && . "$CONFIG_FILE" 2>/dev/null || true\n\n  if [ "${ENABLE_ZRAM_100P:-0}" != 1 ] ||\n     [ "${ZRAM_EMERALD_OC:-0}" != 1 ] ||\n     [ "${LAST_ZRAM_100P:-}" != enabled_max_lock ] ||\n     [ "${ZRAM_RISK_ACK:-}" != explicit_user_enable ] ||\n     [ "${ZRAM_EH_RISK_ACK:-}" != explicit_user_enable_max_lock ]; then\n    STATUS_ALIASES_SKIPPED=0\n    status_write adaptive not_explicitly_authorized 0 none\n    printf \'%s\\n\' \'RESULT: ZRAM_EH_APPLY_REFUSED reason=explicit_max_lock_choice_missing\'\n    return 3\n  fi\n\n  requested="${ZRAM_EH_TARGET_FREQ:-max}"\n  case "$requested" in\n    max) ;;\n    *)\n      is_uint "$requested" || {\n        status_write failed invalid_target 0 "$requested"\n        printf \'%s\\n\' "RESULT: ZRAM_EH_APPLY_FAIL reason=invalid_target target=$requested"\n        return 4\n      }\n    ;;\n  esac\n\n  mkdir -p "$STATE_DIR" 2>/dev/null || true\n  chmod 0700 "$STATE_DIR" 2>/dev/null || true\n  tmp="$BASELINE_FILE.tmp.$$"\n  seen="$STATE_DIR/apply-seen.tmp.$$"\n  printf \'path\\tcanonical_path\\toriginal_min\\tobserved_max\\ttarget\\n\' > "$tmp"\n  : > "$seen"\n\n  nodes=0\n  aliases_skipped=0\n  target_summary=none\n  first_path=none\n  first_original=none\n  first_max=none\n\n  for dir in $ROOTS; do\n    is_eh_node "$dir" || continue\n    identity="$(canonical_dir "$dir")"\n    if grep -Fqx "$identity" "$seen" 2>/dev/null; then\n      aliases_skipped=$((aliases_skipped + 1))\n      continue\n    fi\n    printf \'%s\\n\' "$identity" >> "$seen"\n\n    original_min="$(cat "$dir/min_freq" 2>/dev/null || true)"\n    observed_max="$(cat "$dir/max_freq" 2>/dev/null || true)"\n    is_uint "$original_min" || continue\n    is_uint "$observed_max" || continue\n    [ "$observed_max" -gt 0 ] 2>/dev/null || continue\n\n    if [ "$requested" = max ]; then\n      target="$observed_max"\n    else\n      target="$requested"\n      [ "$target" -le "$observed_max" ] 2>/dev/null || {\n        restore_file "$tmp" >/dev/null 2>&1 || true\n        rm -f "$tmp" "$seen" 2>/dev/null || true\n        STATUS_ALIASES_SKIPPED="$aliases_skipped"\n        status_write failed target_above_kernel_max "$nodes" "$target"\n        printf \'%s\\n\' "RESULT: ZRAM_EH_APPLY_FAIL reason=target_above_kernel_max target=$target max=$observed_max"\n        return 5\n      }\n    fi\n\n    frequency_available "$dir" "$target" || {\n      restore_file "$tmp" >/dev/null 2>&1 || true\n      rm -f "$tmp" "$seen" 2>/dev/null || true\n      STATUS_ALIASES_SKIPPED="$aliases_skipped"\n      status_write failed target_not_available "$nodes" "$target"\n      printf \'%s\\n\' "RESULT: ZRAM_EH_APPLY_FAIL reason=target_not_available path=$dir target=$target"\n      return 6\n    }\n\n    printf \'%s\\t%s\\t%s\\t%s\\t%s\\n\' "$dir" "$identity" "$original_min" "$observed_max" "$target" >> "$tmp"\n    if ! printf \'%s\\n\' "$target" > "$dir/min_freq" 2>/dev/null ||\n       [ "$(cat "$dir/min_freq" 2>/dev/null || true)" != "$target" ]; then\n      restore_file "$tmp" >/dev/null 2>&1 || true\n      rm -f "$tmp" "$seen" 2>/dev/null || true\n      STATUS_ALIASES_SKIPPED="$aliases_skipped"\n      status_write failed write_or_verify_failed "$nodes" "$target"\n      printf \'%s\\n\' "RESULT: ZRAM_EH_APPLY_FAIL reason=write_or_verify_failed path=$dir target=$target"\n      return 7\n    fi\n\n    nodes=$((nodes + 1))\n    target_summary="$target"\n    if [ "$first_path" = none ]; then\n      first_path="$dir"\n      first_original="$original_min"\n      first_max="$observed_max"\n    fi\n  done\n\n  rm -f "$seen" 2>/dev/null || true\n\n  if [ "$nodes" -eq 0 ] 2>/dev/null; then\n    rm -f "$tmp" 2>/dev/null || true\n    STATUS_ALIASES_SKIPPED="$aliases_skipped"\n    status_write unsupported no_matching_devfreq_node 0 none\n    printf \'%s\\n\' \'RESULT: ZRAM_EH_APPLY_FAIL reason=no_matching_devfreq_node\'\n    return 8\n  fi\n\n  mv "$tmp" "$BASELINE_FILE"\n  chmod 0600 "$BASELINE_FILE" 2>/dev/null || true\n  STATUS_ALIASES_SKIPPED="$aliases_skipped"\n  STATUS_PATH="$first_path"\n  STATUS_ORIGINAL_MIN="$first_original"\n  STATUS_OBSERVED_MAX="$first_max"\n  status_write active max_frequency_minimum_lock_verified "$nodes" "$target_summary"\n  printf \'%s\\n\' "RESULT: ZRAM_EH_APPLY_DONE nodes=$nodes aliases_skipped=$aliases_skipped target=$target_summary policy=kernel_exposed_opp_only"\n  return 0\n}\n\nrestore_lock() {\n  if [ ! -s "$BASELINE_FILE" ]; then\n    STATUS_ALIASES_SKIPPED=0\n    status_write adaptive no_baseline 0 none\n    printf \'%s\\n\' \'RESULT: ZRAM_EH_RESTORE_DONE nodes=0 aliases_skipped=0 reason=no_baseline\'\n    return 0\n  fi\n\n  if restore_file "$BASELINE_FILE"; then\n    rm -f "$BASELINE_FILE" 2>/dev/null || true\n    STATUS_ALIASES_SKIPPED="$RESTORE_ALIASES_SKIPPED"\n    status_write adaptive baseline_restored "$RESTORE_NODES" none\n    printf \'%s\\n\' "RESULT: ZRAM_EH_RESTORE_DONE nodes=$RESTORE_NODES aliases_skipped=$RESTORE_ALIASES_SKIPPED"\n    return 0\n  fi\n\n  STATUS_ALIASES_SKIPPED="$RESTORE_ALIASES_SKIPPED"\n  status_write failed baseline_restore_incomplete "$RESTORE_NODES" none\n  printf \'%s\\n\' "RESULT: ZRAM_EH_RESTORE_FAIL reason=baseline_restore_incomplete restored=$RESTORE_NODES failed=$RESTORE_FAILED aliases_skipped=$RESTORE_ALIASES_SKIPPED"\n  return 9\n}\n\nshow_status() {\n  [ -r "$STATUS_FILE" ] && cat "$STATUS_FILE" || {\n    status_write unknown not_evaluated 0 none\n    cat "$STATUS_FILE"\n  }\n  return 0\n}\n\ncase "$MODE" in\n  apply) apply_lock ;;\n  restore|disable) restore_lock ;;\n  status) show_status ;;\n  *)\n    printf \'%s\\n\' "RESULT: ZRAM_EH_CONTROL_FAIL reason=invalid_mode mode=$MODE"\n    exit 2\n  ;;\nesac\n')
write('tools/zram/apply-zram-100p.sh', '#!/system/bin/sh\n# Pixel 10 Thermal & Memory Control - ZRAM 100% apply helper.\n# lz77eh hardware acceleration remains independent from the optional\n# Emerald Hill maximum-frequency minimum lock.\nset -eu\n\nID="pixel-10-pro-xl-thermal-fix"\nCONFIG_FILE="${ZRAM_CONFIG_FILE:-/data/adb/$ID/config.env}"\nMODE="${1:-manual}"\nMODDIR="${MODDIR:-/data/adb/modules/$ID}"\nRESET="$MODDIR/tools/resetprop-rs"\nNORMALIZE="$MODDIR/tools/zram/config-normalize.sh"\nEH_CONTROL="$MODDIR/tools/zram/emerald-hill-control.sh"\nBIGMAX="2147483647"\n\n[ -r "$NORMALIZE" ] && ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$NORMALIZE" >/dev/null 2>&1 || true\n[ -f "$CONFIG_FILE" ] && . "$CONFIG_FILE" 2>/dev/null || true\n\nDEBUG="${DEBUG_MODE:-${debug_mode:-0}}"\nRESTART="${ZRAM_RESTART_MMD:-1}"\nSWAPPINESS="${ZRAM_SWAPPINESS:-100}"\nTHP_MODE="${ZRAM_THP_MODE:-stock}"\n\nlog() { printf \'%s\\n\' "$*"; }\n\ncfg_set() {\n  key="$1"\n  value="$2"\n  mkdir -p "${CONFIG_FILE%/*}" 2>/dev/null || true\n  touch "$CONFIG_FILE" 2>/dev/null || true\n  tmp="$CONFIG_FILE.tmp.$$"\n  grep -v "^${key}=" "$CONFIG_FILE" 2>/dev/null > "$tmp" || true\n  printf \'%s=%s\\n\' "$key" "$value" >> "$tmp"\n  chmod 0600 "$tmp" 2>/dev/null || true\n  mv "$tmp" "$CONFIG_FILE"\n}\n\nlog "=== Apply ZRAM Start ==="\nlog "time=$(date -Is 2>/dev/null || date)"\nlog "mode=$MODE"\nlog "debug=$DEBUG"\nlog "restart_mmd=$RESTART"\nlog "swappiness=$SWAPPINESS"\nlog "thp_mode=$THP_MODE"\n\nif [ ! -x "$RESET" ]; then\n  log "RESULT: ZRAM_APPLY_FAIL reason=resetprop_rs_missing_or_not_executable path=$RESET"\n  exit 2\nfi\n\nprop_set() {\n  key="$1"\n  val="$2"\n  "$RESET" -n "$key" "$val" || {\n    log "RESULT: ZRAM_APPLY_FAIL reason=resetprop_failed key=$key"\n    exit 3\n  }\n  [ "$DEBUG" = 1 ] && log "set $key=$val"\n}\n\ncase "$SWAPPINESS" in\n  \'\'|*[!0-9]*) SWAPPINESS=100 ;;\n  *) [ "$SWAPPINESS" -le 200 ] 2>/dev/null || SWAPPINESS=100 ;;\nesac\ncase "$THP_MODE" in stock|always|madvise|never) ;; *) THP_MODE=stock ;; esac\n\n# Runtime-only ZRAM properties. LMKD policy remains owned by the platform because\n# a late ro.lmk override is not proven to be consumed without an explicit LMKD\n# property reload.\nprop_set mm.zram.maintenance.first_delay_seconds "$BIGMAX"\nprop_set mm.zram.maintenance.periodic_delay_seconds "$BIGMAX"\nprop_set mmd.zram.writeback.max_idle_seconds "$BIGMAX"\nprop_set mmd.zram.comp_algorithm lz77eh\nprop_set mmd.zram.enabled true\nprop_set mmd.zram.size 100%\nprop_set vendor.zram.size 100p\nprop_set persist.device_config.vendor_system_native_boot.zram_size 100p\nprop_set persist.vendor.boot.zram.size 100p\nlmk_swap_low_actual="$(getprop ro.lmk.swap_free_low_percentage 2>/dev/null || true)"\nlog "ZRAM_LMK_SWAP_LOW policy=stock_unmodified actual=${lmk_swap_low_actual:-unset}"\n\nsysctl -w "vm.swappiness=$SWAPPINESS" >/dev/null 2>&1 || prop_set vm.swappiness "$SWAPPINESS"\n\nif [ "$THP_MODE" != stock ] && [ -d /sys/kernel/mm/transparent_hugepage ]; then\n  printf \'%s\\n\' "$THP_MODE" > /sys/kernel/mm/transparent_hugepage/enabled 2>/dev/null || true\n  case "$THP_MODE" in\n    always|madvise|never)\n      printf \'%s\\n\' "$THP_MODE" > /sys/kernel/mm/transparent_hugepage/shmem_enabled 2>/dev/null || true\n    ;;\n  esac\nfi\n\nif [ "$RESTART" = 1 ] && [ "$MODE" != boot_early ] && [ "$MODE" != boot_verified ]; then\n  log \'mmd_restart=requested\'\n  stop mmd 2>/dev/null || setprop ctl.stop mmd 2>/dev/null || true\n  start mmd 2>/dev/null || setprop ctl.start mmd 2>/dev/null || true\nelse\n  log "mmd_restart=skipped mode=$MODE"\nfi\n\neh_state=adaptive\nif [ "$MODE" = boot_early ]; then\n  eh_state=deferred_until_verified_boot\nelif [ "$MODE" = boot_verified ]; then\n  eh_state=deferred_to_service_post_bootguard\nelif [ -r "$EH_CONTROL" ]; then\n  if [ "${ZRAM_EMERALD_OC:-0}" = 1 ] &&\n     [ "${LAST_ZRAM_100P:-}" = enabled_max_lock ] &&\n     [ "${ZRAM_RISK_ACK:-}" = explicit_user_enable ] &&\n     [ "${ZRAM_EH_RISK_ACK:-}" = explicit_user_enable_max_lock ]; then\n    if MODDIR="$MODDIR" ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$EH_CONTROL" apply; then\n      eh_state=max_frequency_minimum_lock_active\n    else\n      cfg_set ZRAM_EMERALD_OC 0\n      cfg_set ZRAM_EH_RISK_ACK none\n      cfg_set LAST_ZRAM_100P enabled_standard\n      MODDIR="$MODDIR" ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$EH_CONTROL" restore >/dev/null 2>&1 || true\n      eh_state=max_lock_failed_fallback_adaptive\n      log \'ZRAM_EH_FALLBACK=adaptive\'\n    fi\n  else\n    MODDIR="$MODDIR" ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$EH_CONTROL" restore >/dev/null 2>&1 || true\n  fi\nelse\n  eh_state=helper_missing_adaptive\nfi\n\nif [ "$DEBUG" = 1 ] || [ "$MODE" != boot_early ]; then\n  log \'== active swaps ==\'\n  cat /proc/swaps 2>/dev/null || true\n  log \'== zram info ==\'\n  for f in disksize comp_algorithm mm_stat; do\n    [ -r "/sys/block/zram0/$f" ] && log "zram0/$f: $(cat "/sys/block/zram0/$f")"\n  done\nfi\n\nlog "RESULT: ZRAM_APPLY_DONE mode=$MODE restart_policy=manual_only swappiness=$SWAPPINESS thp=$THP_MODE eh_state=$eh_state lmk_swap_low_policy=stock_unmodified lmk_swap_low_actual=${lmk_swap_low_actual:-unset} backup_state=runtime_only"\nexit 0\n')
write('tools/zram/config-normalize.sh', '#!/system/bin/sh\n# Normalize Dev.14 ZRAM settings and migrate every legacy Emerald Hill lock\n# state to the safe adaptive hardware-acceleration default.\nset -eu\n\nID="${ID:-pixel-10-pro-xl-thermal-fix}"\nCONFIG_FILE="${ZRAM_CONFIG_FILE:-/data/adb/$ID/config.env}"\n\ncfg_get() {\n  [ -r "$CONFIG_FILE" ] || return 0\n  grep -E "^$1=" "$CONFIG_FILE" 2>/dev/null | tail -n 1 | sed "s/^$1=//" | tr -d \'\\r\'\n}\n\ncfg_set() {\n  key="$1"\n  value="$2"\n  mkdir -p "${CONFIG_FILE%/*}" 2>/dev/null || true\n  touch "$CONFIG_FILE" 2>/dev/null || true\n  tmp="$CONFIG_FILE.tmp.$$"\n  grep -v "^${key}=" "$CONFIG_FILE" 2>/dev/null > "$tmp" || true\n  printf \'%s=%s\\n\' "$key" "$value" >> "$tmp"\n  chmod 0600 "$tmp" 2>/dev/null || true\n  mv "$tmp" "$CONFIG_FILE"\n}\n\nenabled="$(cfg_get ENABLE_ZRAM_100P)"\noc="$(cfg_get ZRAM_EMERALD_OC)"\nlast="$(cfg_get LAST_ZRAM_100P)"\neh_ack="$(cfg_get ZRAM_EH_RISK_ACK)"\nmigrated=none\n\ncase "$enabled" in 0|1) ;; *) enabled=\'\' ;; esac\ncase "$oc" in 0|1) ;; *) oc=0; cfg_set ZRAM_EMERALD_OC 0 ;; esac\ncase "$eh_ack" in explicit_user_enable_max_lock|none|disabled_by_user) ;; *) eh_ack=none; cfg_set ZRAM_EH_RISK_ACK none ;; esac\n\n# Dev.13 used LAST_ZRAM_100P=enabled without a dedicated EH acknowledgement.\n# It is always migrated to adaptive so an old duplicate baseline cannot relock.\nif [ "$last" = enabled ]; then\n  last=enabled_standard\n  oc=0\n  eh_ack=none\n  cfg_set LAST_ZRAM_100P enabled_standard\n  cfg_set ZRAM_EMERALD_OC 0\n  cfg_set ZRAM_EH_RISK_ACK none\n  migrated=legacy_enabled_to_adaptive\nfi\n\ncase "$last" in\n  disabled|enabled_standard|enabled_max_lock) ;;\n  *)\n    case "$enabled" in\n      1) last=enabled_standard; cfg_set LAST_ZRAM_100P enabled_standard ;;\n      0) last=disabled; cfg_set LAST_ZRAM_100P disabled ;;\n      *) last=\'\' ;;\n    esac\n  ;;\nesac\n\nif [ "$oc" = 1 ]; then\n  if [ "$last" != enabled_max_lock ] || [ "$eh_ack" != explicit_user_enable_max_lock ]; then\n    oc=0\n    eh_ack=none\n    [ "$enabled" = 1 ] && last=enabled_standard\n    cfg_set ZRAM_EMERALD_OC 0\n    cfg_set ZRAM_EH_RISK_ACK none\n    [ "$enabled" = 1 ] && cfg_set LAST_ZRAM_100P enabled_standard\n    migrated=unauthorized_lock_to_adaptive\n  fi\nelse\n  if [ "$last" = enabled_max_lock ]; then\n    last=enabled_standard\n    cfg_set LAST_ZRAM_100P enabled_standard\n    migrated=inconsistent_choice_to_adaptive\n  fi\n  if [ "$eh_ack" = explicit_user_enable_max_lock ]; then\n    eh_ack=none\n    cfg_set ZRAM_EH_RISK_ACK none\n  fi\nfi\n\ncase "$(cfg_get ZRAM_EH_TARGET_FREQ)" in\n  max) ;;\n  \'\'|*[!0-9]*) cfg_set ZRAM_EH_TARGET_FREQ max ;;\nesac\n\ncase "$(cfg_get ZRAM_THP_MODE)" in\n  stock|always|madvise|never) ;;\n  *) cfg_set ZRAM_THP_MODE stock ;;\nesac\n\nswappiness="$(cfg_get ZRAM_SWAPPINESS)"\ncase "$swappiness" in\n  \'\'|*[!0-9]*) cfg_set ZRAM_SWAPPINESS 100 ;;\n  *)\n    if [ "$swappiness" -gt 200 ] 2>/dev/null; then\n      cfg_set ZRAM_SWAPPINESS 100\n    fi\n  ;;\nesac\n\nprintf \'%s\\n\' "RESULT: ZRAM_CONFIG_NORMALIZE_DONE oc=$oc last=${last:-unset} eh_ack=${eh_ack:-none} migrated=$migrated target=$(cfg_get ZRAM_EH_TARGET_FREQ) thp=$(cfg_get ZRAM_THP_MODE) swappiness=$(cfg_get ZRAM_SWAPPINESS)"\nexit 0\n')
write('service.sh', '#!/system/bin/sh\nMODDIR=${0%/*}\nID="pixel-10-pro-xl-thermal-fix"\nG="$MODDIR/guard"\nL="$G/bootguard.log"\nH="$MODDIR/health.log"\nCONFIG_FILE="/data/adb/$ID/config.env"\nNORMALIZE="$MODDIR/tools/zram/config-normalize.sh"\nZRAM_APPLY="$MODDIR/tools/zram/apply-zram-100p.sh"\nEH_CONTROL="$MODDIR/tools/zram/emerald-hill-control.sh"\nmkdir -p "$G"\n\nprintf \'timestamp_start=%s\\n\' "$(date +%s 2>/dev/null || echo unknown)" > "$H"\nprintf \'%s\\n\' \'health_log_model=verified_runtime_guard_plus_zram_100p_eh_deferred_v6\' >> "$H"\nprintf \'%s\\n\' \'lmk_swap_low_policy=stock_unmodified\' >> "$H"\n\n[ -r "$NORMALIZE" ] && ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$NORMALIZE" >> "$H" 2>&1 || true\nif [ -f "$CONFIG_FILE" ]; then\n  . "$CONFIG_FILE" 2>/dev/null || true\nfi\n\n# Standard lz77eh ZRAM properties may be prepared early. The optional Emerald\n# Hill maximum-frequency minimum lock is deferred until Bootguard verifies the\n# completed Android boot and active Thermal runtime.\nif [ "${ENABLE_ZRAM_100P:-0}" = 1 ] && [ "${ZRAM_RISK_ACK:-}" = explicit_user_enable ]; then\n  printf \'%s SERVICE_ZRAM action=apply mode=boot_early resetprop=required mmd_restart=skip eh=deferred lmk=stock\\n\' "$(date -Is 2>/dev/null || date)" >> "$L"\n  if [ -r "$ZRAM_APPLY" ]; then\n    sh "$ZRAM_APPLY" boot_early >> "$H" 2>&1 ||\n      printf \'%s\\n\' \'SERVICE_ZRAM result=apply_failed_nonfatal\' >> "$H"\n  else\n    printf \'%s\\n\' \'SERVICE_ZRAM result=apply_script_absent\' >> "$H"\n  fi\nelse\n  printf \'%s SERVICE_ZRAM action=skip enabled=%s ack=%s\\n\' \\\n    "$(date -Is 2>/dev/null || date)" "${ENABLE_ZRAM_100P:-0}" "${ZRAM_RISK_ACK:-unset}" >> "$L"\nfi\n\nprintf \'%s SERVICE_START action=verified_runtime_health optional_zram_supported=true\\n\' "$(date -Is 2>/dev/null || date)" >> "$L"\nwhile [ "$(getprop sys.boot_completed 2>/dev/null)" != 1 ]; do\n  sleep 1\ndone\n\nsleep "${BOOTGUARD_SUCCESS_SETTLE_SECONDS:-30}"\n\n{\n  printf \'timestamp_complete=%s\\n\' "$(date +%s 2>/dev/null || echo unknown)"\n  printf \'boot_completed=%s\\n\' "$(getprop sys.boot_completed 2>/dev/null || echo unknown)"\n  printf \'boot_id=%s\\n\' "$(cat /proc/sys/kernel/random/boot_id 2>/dev/null || echo unknown)"\n  printf \'\\n== flags ==\\n\'\n  [ -e "$MODDIR/disable" ] && printf \'%s\\n\' disable=present || printf \'%s\\n\' disable=absent\n  [ -e "$MODDIR/skip_mount" ] && printf \'%s\\n\' skip_mount=present || printf \'%s\\n\' skip_mount=absent\n  [ -e "$MODDIR/remove" ] && printf \'%s\\n\' remove=present || printf \'%s\\n\' remove=absent\n  printf \'\\n== mounts ==\\n\'\n  grep -E "$ID|/vendor/etc/thermal_info_config|/vendor/etc/fstab.zram.100p" /proc/mounts 2>/dev/null || true\n  printf \'%s\\n\' health_log_complete=yes\n} >> "$H" 2>&1\n\nif [ -s "$MODDIR/tools/debug/status-lib.sh" ]; then\n  sh "$MODDIR/tools/debug/status-lib.sh" update >> "$H" 2>&1 || true\nfi\n\nbootguard_verified=0\nif [ -s "$MODDIR/tools/bootguard/bootguard-lib.sh" ]; then\n  if MODDIR="$MODDIR" CONFIG_FILE="$CONFIG_FILE" sh "$MODDIR/tools/bootguard/bootguard-lib.sh" success-verify >> "$H" 2>&1; then\n    bootguard_verified=1\n    printf \'%s\\n\' \'BOOTGUARD_RUNTIME_VERIFICATION=pass\' >> "$H"\n  else\n    printf \'%s\\n\' \'BOOTGUARD_RUNTIME_VERIFICATION=deferred_pending_preserved\' >> "$H"\n  fi\nfi\n\n# Android may rewrite selected ZRAM properties after early service startup.\n# Reapply exactly once after verified boot. LMKD remains stock and this mode\n# never restarts mmd.\nif [ "$bootguard_verified" = 1 ] &&\n   [ "${ENABLE_ZRAM_100P:-0}" = 1 ] &&\n   [ "${ZRAM_RISK_ACK:-}" = explicit_user_enable ]; then\n  if [ -r "$ZRAM_APPLY" ] && sh "$ZRAM_APPLY" boot_verified >> "$H" 2>&1; then\n    printf \'%s\\n\' \'SERVICE_ZRAM_POST_BOOT result=zram_properties_reapplied_no_mmd_restart lmk_policy=stock_unmodified\' >> "$H"\n  else\n    printf \'%s\\n\' \'SERVICE_ZRAM_POST_BOOT result=reapply_failed_nonfatal\' >> "$H"\n  fi\nfi\n\n# The lock is a post-verification enhancement, never a boot prerequisite.\n# Any failure restores adaptive devfreq and remains nonfatal.\nif [ -r "$EH_CONTROL" ]; then\n  if [ "$bootguard_verified" = 1 ] &&\n     [ "${ENABLE_ZRAM_100P:-0}" = 1 ] &&\n     [ "${ZRAM_EMERALD_OC:-0}" = 1 ] &&\n     [ "${LAST_ZRAM_100P:-}" = enabled_max_lock ] &&\n     [ "${ZRAM_RISK_ACK:-}" = explicit_user_enable ] &&\n     [ "${ZRAM_EH_RISK_ACK:-}" = explicit_user_enable_max_lock ]; then\n    if MODDIR="$MODDIR" ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$EH_CONTROL" apply >> "$H" 2>&1; then\n      printf \'%s\\n\' \'SERVICE_ZRAM_EH result=max_frequency_minimum_lock_active\' >> "$H"\n    else\n      MODDIR="$MODDIR" ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$EH_CONTROL" restore >> "$H" 2>&1 || true\n      printf \'%s\\n\' \'SERVICE_ZRAM_EH result=apply_failed_adaptive_fallback\' >> "$H"\n    fi\n  else\n    MODDIR="$MODDIR" ZRAM_CONFIG_FILE="$CONFIG_FILE" sh "$EH_CONTROL" restore >> "$H" 2>&1 || true\n    printf \'%s\\n\' "SERVICE_ZRAM_EH result=adaptive bootguard_verified=$bootguard_verified requested=${ZRAM_EMERALD_OC:-0} eh_ack=${ZRAM_EH_RISK_ACK:-none}" >> "$H"\n  fi\nfi\n\nif [ -s "$MODDIR/tools/debug/status-lib.sh" ]; then\n  sh "$MODDIR/tools/debug/status-lib.sh" update >> "$H" 2>&1 || true\nfi\n\nexit 0\n')
write('tests/test-dev14-eh-safety.sh', '#!/usr/bin/env bash\nset -euo pipefail\n\nrepo_root="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd -P)"\ncontrol="$repo_root/tools/zram/emerald-hill-control.sh"\napply="$repo_root/tools/zram/apply-zram-100p.sh"\nnormalize="$repo_root/tools/zram/config-normalize.sh"\nservice="$repo_root/service.sh"\ninstall_menu="$repo_root/tools/menu/install-options-menu.sh"\naction_dashboard="$repo_root/tools/action-dashboard.sh"\ninstall_finalize="$repo_root/tools/install-finalize.sh"\nmodule_prop="$repo_root/module.prop"\n\ntmp="$(mktemp -d)"\ntrap \'rm -rf "$tmp"\' EXIT\nmkdir -p "$tmp/physical/eh-device" "$tmp/class" "$tmp/platform/soc/devfreq" "$tmp/state" "$tmp/data"\n\nprintf \'%s\\n\' 200000000 > "$tmp/physical/eh-device/min_freq"\nprintf \'%s\\n\' 1066000000 > "$tmp/physical/eh-device/max_freq"\nprintf \'%s\\n\' \'200000000 400000000 800000000 1066000000\' > "$tmp/physical/eh-device/available_frequencies"\nln -s ../physical/eh-device "$tmp/class/eh_freq"\nln -s ../../../physical/eh-device "$tmp/platform/soc/devfreq/eh_freq"\n\nconfig="$tmp/data/config.env"\nprintf \'%s\\n\' \\\n  \'ENABLE_ZRAM_100P=1\' \\\n  \'ZRAM_RISK_ACK=explicit_user_enable\' \\\n  \'ZRAM_EH_RISK_ACK=explicit_user_enable_max_lock\' \\\n  \'LAST_ZRAM_100P=enabled_max_lock\' \\\n  \'ZRAM_EMERALD_OC=1\' \\\n  \'ZRAM_EH_TARGET_FREQ=max\' \\\n  \'ZRAM_THP_MODE=stock\' \\\n  \'ZRAM_SWAPPINESS=100\' > "$config"\n\nfor file in "$control" "$apply" "$normalize" "$service" "$install_menu" "$action_dashboard" "$install_finalize"; do\n  bash -n "$file"\ndone\n\nMODDIR="$repo_root" \\\nZRAM_CONFIG_FILE="$config" \\\nZRAM_EH_STATE_DIR="$tmp/state" \\\nZRAM_EH_DEVFREQ_ROOTS="$tmp/class/* $tmp/platform/*/devfreq/*" \\\nsh "$control" apply > "$tmp/apply.log"\n\ngrep -Fq \'RESULT: ZRAM_EH_APPLY_DONE nodes=1 aliases_skipped=1 target=1066000000\' "$tmp/apply.log"\n[[ "$(cat "$tmp/physical/eh-device/min_freq")" = 1066000000 ]]\n[[ "$(wc -l < "$tmp/state/baseline.tsv" | tr -d \' \')" = 2 ]]\ngrep -Fq \'schema=pixel-zram-eh-status-v2\' "$tmp/state/status.env"\ngrep -Fq \'aliases_skipped=1\' "$tmp/state/status.env"\ngrep -Fq \'apply_mode=one_shot_post_bootguard\' "$tmp/state/status.env"\n\n# Simulate the unsafe duplicate Dev.13 baseline: first row has the true 200 MHz\n# original, while the alias row observed 1066 MHz after the first write.\nprintf \'%s\\n\' \\\n  $\'path\\toriginal_min\\tobserved_max\\ttarget\' \\\n  "$tmp/class/eh_freq"$\'\\t200000000\\t1066000000\\t1066000000\' \\\n  "$tmp/platform/soc/devfreq/eh_freq"$\'\\t1066000000\\t1066000000\\t1066000000\' \\\n  > "$tmp/state/baseline.tsv"\nprintf \'%s\\n\' 1066000000 > "$tmp/physical/eh-device/min_freq"\n\nMODDIR="$repo_root" \\\nZRAM_CONFIG_FILE="$config" \\\nZRAM_EH_STATE_DIR="$tmp/state" \\\nZRAM_EH_DEVFREQ_ROOTS="$tmp/class/* $tmp/platform/*/devfreq/*" \\\nsh "$control" restore > "$tmp/restore.log"\n\ngrep -Fq \'RESULT: ZRAM_EH_RESTORE_DONE nodes=1 aliases_skipped=1\' "$tmp/restore.log"\n[[ "$(cat "$tmp/physical/eh-device/min_freq")" = 200000000 ]]\n\n# A Dev.13 legacy lock choice must normalize to adaptive.\nprintf \'%s\\n\' \\\n  \'ENABLE_ZRAM_100P=1\' \\\n  \'ZRAM_RISK_ACK=explicit_user_enable\' \\\n  \'LAST_ZRAM_100P=enabled\' \\\n  \'ZRAM_EMERALD_OC=1\' > "$config"\nZRAM_CONFIG_FILE="$config" sh "$normalize" > "$tmp/normalize.log"\ngrep -Fq \'migrated=legacy_enabled_to_adaptive\' "$tmp/normalize.log"\ngrep -Fq \'ZRAM_EMERALD_OC=0\' "$config"\ngrep -Fq \'LAST_ZRAM_100P=enabled_standard\' "$config"\ngrep -Fq \'ZRAM_EH_RISK_ACK=none\' "$config"\n\nif grep -Fq \'prop_set ro.lmk.swap_free_low_percentage\' "$apply"; then\n  printf \'%s\\n\' \'FAIL dev14_lmk_override_reintroduced\'\n  exit 1\nfi\ngrep -Fq \'lmk_swap_low_policy=stock_unmodified\' "$apply"\ngrep -Fq \'lmk_swap_low_policy=stock_unmodified\' "$service"\n\ngrep -Fq \'polling_index=1\' "$install_menu"\ngrep -Fq \'current_profile=stock\' "$install_menu"\ngrep -Fq \'zram_index=0\' "$install_menu"\ngrep -Fq \'ptune_index=1\' "$install_menu"\ngrep -Fq \'debug_index=0\' "$install_menu"\ngrep -Fq \'Max lock (more power/heat)\' "$install_menu"\ngrep -Fq \'Adaptive (recommended)\' "$action_dashboard"\n\ngrep -Fq \'ptune_risk_ack=\' "$install_finalize"\ngrep -Fq \'zram_risk_ack=\' "$install_finalize"\ngrep -Fq \'zram_eh_risk_ack=\' "$install_finalize"\nif grep -Fq \'"risk_ack=\' "$install_finalize"; then\n  printf \'%s\\n\' \'FAIL dev14_generic_risk_ack_reintroduced\'\n  exit 1\nfi\n\nif grep -Fq \'while :; do\' "$service"; then\n  printf \'%s\\n\' \'FAIL dev14_unbounded_eh_watcher_present\'\n  exit 1\nfi\n\ngrep -Fq \'version=2.0.0-alpha.3-dev.14\' "$module_prop"\ngrep -Fq \'versionCode=1016225\' "$module_prop"\n\nprintf \'%s\\n\' \'PASS dev14_physical_eh_alias_deduplication\'\nprintf \'%s\\n\' \'PASS dev14_migration_safe_duplicate_baseline_restore\'\nprintf \'%s\\n\' \'PASS dev14_legacy_lock_migrates_to_adaptive\'\nprintf \'%s\\n\' \'PASS dev14_stock_lmk_policy\'\nprintf \'%s\\n\' \'PASS dev14_safe_fresh_defaults\'\nprintf \'%s\\n\' \'PASS dev14_distinct_risk_observability\'\nprintf \'%s\\n\' \'RESULT: PIXEL_THERMAL_DEV14_EH_SAFETY_TEST_PASS\'\n')
write('.github/workflows/v2-dev14-runtime-ci.yml', "name: V2 Dev.14 EH safety regression\n\non:\n  pull_request:\n    branches:\n      - v2\n  workflow_dispatch:\n\npermissions:\n  contents: read\n\njobs:\n  dev14-eh-safety:\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Dev.14 shell and runtime fixtures\n        shell: bash\n        run: |\n          set -euo pipefail\n          bash -n tests/test-dev14-eh-safety.sh\n          bash -n tools/zram/emerald-hill-control.sh\n          bash -n tools/zram/apply-zram-100p.sh\n          bash -n tools/zram/config-normalize.sh\n          bash -n tools/menu/install-options-menu.sh\n          bash -n tools/action-dashboard.sh\n          bash -n tools/install-finalize.sh\n          bash -n service.sh\n          bash tests/test-dev14-eh-safety.sh\n\n      - name: Preserve Dev.12 ZRAM regression\n        shell: bash\n        run: |\n          set -euo pipefail\n          bash tests/test-zram-eh-dev12.sh\n")
write('release-notes/2.0.0-alpha.3-dev.14.md', '# 2.0.0 Alpha 3 Dev 14\n\n## Purpose\n\nDev.14 is the corrective test build after the Dev.13 Mustang live-verification findings. It keeps the verified Thermal, Bootguard, ZRAM 100p, `lz77eh`, swappiness and post-OTA state-refresh work, while making Emerald Hill adaptive operation the safe daily default.\n\n## Emerald Hill safety\n\n- Deduplicates physical devfreq devices across `/sys/class` and `/sys/devices/platform` aliases.\n- Keeps the preferred class path while recording one authoritative baseline per physical node.\n- Restores legacy Dev.13 duplicate baselines once per physical device, preserving the first true original minimum.\n- Adds status schema v2 with path, original minimum, observed maximum, target, alias count and one-shot post-Bootguard mode.\n- Migrates legacy or inconsistent lock choices to adaptive operation.\n- Keeps the optional maximum-frequency minimum lock behind a dedicated explicit acknowledgement.\n- Describes the lock accurately: it does not exceed the kernel maximum, but can increase power and heat by preventing downclocking.\n\n## ZRAM and LMK policy\n\n- Keeps ZRAM 100 percent, `lz77eh` and `vm.swappiness=100`.\n- Removes the unverified late `ro.lmk.swap_free_low_percentage=1` override.\n- Records `lmk_swap_low_policy=stock_unmodified`.\n- Keeps ZRAM enhancement operation independent from the optional EH lock.\n\n## Installer and observability\n\n- Fresh choices now start at Stock Polling, Stock Thermal, ZRAM disabled, EH disabled, pTune override off and silent logging.\n- Use-last behavior remains available separately.\n- pTune, ZRAM and EH risk acknowledgements are recorded in distinct fields.\n- Action and installer labels use Adaptive and Maximum lock terminology instead of calling the kernel-exposed maximum an overclock.\n\n## Verification boundary\n\nRepository CI and deterministic packaging are required before producing a device test ZIP. This development build is not a public release and does not change stable or prerelease update channels. A fresh install, reboot and Mustang runtime verification remain mandatory before any release decision.\n')

replace_once('tools/menu/install-options-menu.sh', 'apply_zram() {\n  case "$1" in\n    0|disabled)\n      cfg_set ENABLE_ZRAM_100P 0\n      cfg_set ZRAM_EMERALD_OC 0\n      cfg_set ZRAM_RESTART_MMD 0\n      cfg_set ZRAM_RISK_ACK disabled_by_user\n      cfg_set LAST_ZRAM_100P disabled\n    ;;\n    enabled_standard)\n      cfg_set ENABLE_ZRAM_100P 1\n      cfg_set ZRAM_EMERALD_OC 0\n      cfg_set ZRAM_RESTART_MMD 1\n      cfg_set ZRAM_RISK_ACK explicit_user_enable\n      cfg_set LAST_ZRAM_100P enabled_standard\n    ;;\n    *)\n      cfg_set ENABLE_ZRAM_100P 1\n      cfg_set ZRAM_EMERALD_OC 1\n      cfg_set ZRAM_RESTART_MMD 1\n      cfg_set ZRAM_RISK_ACK explicit_user_enable\n      cfg_set LAST_ZRAM_100P enabled\n    ;;\n  esac\n}\n', 'apply_zram() {\n  case "$1" in\n    0|disabled)\n      cfg_set ENABLE_ZRAM_100P 0\n      cfg_set ZRAM_EMERALD_OC 0\n      cfg_set ZRAM_RESTART_MMD 0\n      cfg_set ZRAM_RISK_ACK disabled_by_user\n      cfg_set ZRAM_EH_RISK_ACK disabled_by_user\n      cfg_set LAST_ZRAM_100P disabled\n    ;;\n    enabled_max_lock)\n      cfg_set ENABLE_ZRAM_100P 1\n      cfg_set ZRAM_EMERALD_OC 1\n      cfg_set ZRAM_RESTART_MMD 1\n      cfg_set ZRAM_RISK_ACK explicit_user_enable\n      cfg_set ZRAM_EH_RISK_ACK explicit_user_enable_max_lock\n      cfg_set LAST_ZRAM_100P enabled_max_lock\n    ;;\n    *)\n      cfg_set ENABLE_ZRAM_100P 1\n      cfg_set ZRAM_EMERALD_OC 0\n      cfg_set ZRAM_RESTART_MMD 1\n      cfg_set ZRAM_RISK_ACK explicit_user_enable\n      cfg_set ZRAM_EH_RISK_ACK none\n      cfg_set LAST_ZRAM_100P enabled_standard\n    ;;\n  esac\n}\n')
replace_once('tools/menu/install-options-menu.sh', 'zram_summary_label() {\n  _z="$(cfg_get LAST_ZRAM_100P)"\n  _oc="$(cfg_get ZRAM_EMERALD_OC)"\n  case "$_z" in\n    disabled) printf \'%s\\n\' \'disabled\' ;;\n    enabled_standard) printf \'%s\\n\' \'enabled (Standard / No OC)\' ;;\n    *)\n      if [ "$_oc" = "0" ]; then\n        printf \'%s\\n\' \'enabled (Standard / No OC)\'\n      else\n        printf \'%s\\n\' \'enabled (1.066GHz EH OC)\'\n      fi\n    ;;\n  esac\n}\n', 'zram_summary_label() {\n  _z="$(cfg_get LAST_ZRAM_100P)"\n  case "$_z" in\n    disabled) printf \'%s\\n\' \'disabled\' ;;\n    enabled_max_lock) printf \'%s\\n\' \'enabled (EH max lock; more power/heat)\' ;;\n    *) printf \'%s\\n\' \'enabled (adaptive; recommended)\' ;;\n  esac\n}\n')
